import FreeCAD as App
import Part
import Sketcher
import math
from pathlib import Path

# Initialize document
doc = App.newDocument("HexNut")

# --- Parameters ---
# Define a VarSet to hold editable parameters
params = doc.addObject("App::VarSet", "Parameters")
params.addProperty("App::PropertyLength", "hole_diameter", "Dimensions", "Diameter of the central hole")
params.addProperty("App::PropertyLength", "nut_thickness", "Dimensions", "Thickness of the nut body")
params.addProperty("App::PropertyLength", "across_flats", "Dimensions", "Distance across flats of the hexagon")

# Set default values as per instructions
params.hole_diameter = 8.0
params.nut_thickness = 10.0
params.across_flats = 13.0

# --- Body ---
body = doc.addObject("PartDesign::Body", "Body")

# --- Base Sketch (Hexagon) ---
# Create sketch on XY plane
sketch_hex = body.newObject("Sketcher::SketchObject", "HexSketch")
sketch_hex.Placement = App.Placement(App.Vector(0, 0, 0))
sketch_hex.ConstrainAutomatic = False
sketch_hex.ConstrainAuto = False
sketch_hex.MapMode = "FlatFace"

# Calculate geometry
across_corners_val = params.across_flats / math.cos(math.radians(30))
R = across_corners_val
sqrt3 = math.sqrt(3)

# Define vertices for a regular hexagon centered at origin, flat sides parallel to X axis
v1 = App.Vector(R, 0, 0)
v2 = App.Vector(R/2, R*sqrt3/2, 0)
v3 = App.Vector(-R/2, R*sqrt3/2, 0)
v4 = App.Vector(-R, 0, 0)
v5 = App.Vector(-R/2, -R*sqrt3/2, 0)
v6 = App.Vector(R/2, -R*sqrt3/2, 0)

# Add lines
sketch_hex.addGeometry(Part.LineSegment(v1, v2), False)
sketch_hex.addGeometry(Part.LineSegment(v2, v3), False)
sketch_hex.addGeometry(Part.LineSegment(v3, v4), False)
sketch_hex.addGeometry(Part.LineSegment(v4, v5), False)
sketch_hex.addGeometry(Part.LineSegment(v5, v6), False)
sketch_hex.addGeometry(Part.LineSegment(v6, v1), False)

# Add constraints to make it a perfect hexagon
# Coincident all vertices to center (0,0)
